def _iter_lambda_dirs(lambdas_root: Path) -> list[Path]:
    if not lambdas_root.exists():
        return []
    dirs = []
    for domain_dir in lambdas_root.iterdir():
        if not domain_dir.is_dir():
            continue
        for lambda_dir in domain_dir.iterdir():
            if lambda_dir.is_dir():
